<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Http,Storage};
use App\Models\{User,MarketingChannelConnection};
class MarketingImagePublishingTest extends TestCase {
 use RefreshDatabase;
 private function setupPost(){Http::preventStrayRequests();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$this->actingAs($u);config(['app.url'=>'https://shop.example','services.facebook.client_id'=>'publish-test','services.facebook.client_secret'=>'test-secret','marketing.social_publishing_enabled'=>true,'marketing.execution_enabled'=>false]);Storage::fake('public');Storage::fake('local');$im=imagecreatetruecolor(50,50);ob_start();imagejpeg($im);Storage::disk('public')->put('test.jpg',ob_get_clean());imagedestroy($im);$product=\App\Models\Product::create(['title'=>'Publishing fixture','handle'=>'publishing-fixture','status'=>'active','base_price'=>25]);$image=\App\Models\ProductImage::create(['product_id'=>$product->id,'path'=>'test.jpg','position'=>0]);$accounts=[];foreach(['facebook','instagram'] as $platform)$accounts[]=MarketingChannelConnection::create(['merchant_key'=>app(\App\Services\Marketing\MarketingChannels::class)->merchant(),'platform'=>$platform,'provider_account_id'=>$platform==='facebook'?'123':'456','linked_page_id'=>$platform==='instagram'?'123':null,'app_id'=>'publish-test','name'=>$platform,'access_token'=>'PRIVATE-TOKEN','permissions'=>['pages_show_list','pages_read_engagement','pages_manage_posts','instagram_basic','instagram_content_publish'],'tasks'=>['CREATE_CONTENT'],'authorized_by'=>$u->id,'state'=>'connected']);return ['id'=>(string)\Illuminate\Support\Str::uuid(),'version'=>0,'title'=>'Publishing test','copy'=>'JW Marketing Studio publishing test. No offer or product claim.','targets'=>array_column(array_map(fn($a)=>$a->toArray(),$accounts),'id'),'copies'=>[],'asset'=>'image:'.$image->id,'type'=>'Post','tz'=>'Asia/Kuala_Lumpur'];}
 public function test_two_image_destinations_publish_once_and_keep_receipts(){ $p=$this->setupPost();Http::fake(['*/123/photos'=>Http::response(['id'=>'photo-1','post_id'=>'123_post-1']),'*/456/media'=>Http::response(['id'=>'container-1']),'*/container-1*'=>Http::response(['status_code'=>'FINISHED']),'*/456/media_publish'=>Http::response(['id'=>'ig-post-1'])]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Published')->assertDontSee('PRIVATE-TOKEN');$this->postJson('/admin/marketing/posts/data/publish',$p)->assertStatus(409);Http::assertSentCount(4);$this->assertDatabaseCount('marketing_post_attempts',2); }
 public function test_unknown_submit_does_not_retry_or_duplicate_successful_target(){ $p=$this->setupPost();Http::fake(['*/123/photos'=>Http::response(['id'=>'photo-1','post_id'=>'123_post-1']),'*/456/media'=>Http::response(['error'=>['code'=>2,'message'=>'PRIVATE-TOKEN']],503)]);$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Needs attention')->assertDontSee('PRIVATE-TOKEN');$this->postJson('/admin/marketing/posts/data/refresh',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk();Http::assertSentCount(2); }
 public function test_container_wait_uses_known_container_and_never_creates_another(){ $p=$this->setupPost();$p['targets']=[$p['targets'][1]];Http::fake(['*/456/media'=>Http::response(['id'=>'container-1']),'*/container-1*'=>Http::sequence()->push(['status_code'=>'IN_PROGRESS'])->push(['status_code'=>'FINISHED']),'*/456/media_publish'=>Http::response(['id'=>'ig-post-1'])]);$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Publishing');$this->postJson('/admin/marketing/posts/data/refresh',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk()->assertJsonPath('post.status','Published');Http::assertSentCount(4); }
 public function test_publishing_gate_stops_before_network_and_delivery_image_requires_signature(){ $p=$this->setupPost();config(['marketing.social_publishing_enabled'=>false]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertStatus(423);$this->get('/marketing/post-delivery/1')->assertForbidden();Http::assertNothingSent(); }
}
